import React, { useRef, useState } from "react";
import styled from "styled-components";
import test from "../utils/test.txt";
import { apiGetVirulenceInfo } from "../service/virulence";
import { apiGetPlasmidInfo } from "../service/plasmid";
import { apiGetAmrInfo } from "../service/amr";
import { apiCreateSample } from "../service/sample";

const Container = styled.div`
  margin-top: 50px;
  display: flex;
  justify-content: center;
`;
const Wrapper = styled.div`
  width: 90%;
`;
const ButtonResetWrapper = styled.div`
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
`;
const TextAreaWrapper = styled.div`
  width: ${(props) => (props.$selectedFile ? "0px" : "100%")};
  height: ${(props) => (props.$selectedFile ? "0" : "250px")};
  border-radius: 5px;
  border: 1px solid #4a4b4c;
  display: ${(props) => (props.$selectedFile ? "none" : "visible")};
  margin-bottom: ${(props) => (props.$selectedFile ? "0" : "10px")};
  display: flex;
  justify-content: center;
  align-items: center;
`;
const TextArea = styled.textarea`
  display: ${(props) => (props.$selectedFile ? "none" : "visible")};
  width: calc(100% - 20px);
  height: calc(100% - 22px);
  max-height: 250px;
  padding: 9px;
  border-radius: 5px;
  border: 3px solid transparent;
  &:focus {
    outline: none;
    border: 3px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -webkit-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -moz-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
`;
const Input = styled.input`
  display: ${(props) => (props.$text ? "none" : "visible")};
  height: 30px;
  &::-webkit-file-upload-button {
    height: 30px;
    border: none;
    cursor: pointer;
  }
  border: 1px solid #6c757d;
  border-radius: 5px 4px 4px 5px;
  cursor: pointer;
`;
const Example = styled.div`
  cursor: pointer;
  color: #6c757d;
  font-size: 14px;
  margin-bottom: 10px;
  max-width: 300px;
  display: ${(props) => (props.$example ? "none" : "visible")};
`;
const ButtonReset = styled.button`
  display: ${(props) => (props.$visible ? "visible" : "none")};
  max-width: 70px;
  padding: 5px 10px;
  background-color: #6c757d;
  color: white;
  border: none;
  border-radius: 5px;
  margin-top: 5px;
  cursor: pointer;
`;
const Hr = styled.hr`
  margin-top: 10px;
  width: 100%;
  height: 1px;
  background-color: #c7c8c9;
`;
const Form = styled.form`
  width: 100%;
`;
const More = styled.div`
  display: ${(props) => (props.$visible || props.text ? "visible" : "none")};
`;
const WrapperItem = styled.div`
  margin-top: 20px;
`;
const Title = styled.h2`
  margin-bottom: 5px;
`;
const Organism = styled.div`
  display: grid;
  grid-template-columns: 1fr 20px 1fr;
  grid-template-rows: 1fr 10px 1fr;
`;
const OrganismInput = styled.input`
  width: 95%;
  border-radius: 5px;
  border: 1px solid #dee2e6;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -webkit-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -moz-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
  @media (max-width: 500px) {
    width: 90%;
  }
  padding: 8px;
`;
const Annotation = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  justify-content: space-between;
`;
const AnnotationCol = styled.div`
  width: 18%;
  flex-grow: 1;
  min-width: 140px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 250px;
`;
const AnnotationItem = styled.div`
  display: flex;
  gap: 10px;
`;
const AnnotationInput = styled.input`
  width: 70%;
  border-radius: 5px;
  border: 1px solid #dee2e6;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -webkit-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -moz-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
  &::-webkit-file-upload-button {
    margin-top: -15px;
    border: none;
    margin-left: -10px;
    border-radius: 5px;
    height: 40px;
    margin-bottom: -10px;
  }
  padding: 8px;
`;
const Selection = styled.select`
  width: ${(props) => props.$w};
  border-radius: 5px;
  border: 1px solid #dee2e6;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -webkit-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -moz-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
  padding: 8px;
  min-width: 60px;
`;
const Replicons = styled.table`
  width: 100%;
`;
const RepliconsRow = styled.tr``;
const RepliconsCol = styled.td`
  /* display: flex; */
`;
const RepliconsInput = styled.input`
  border-radius: 5px;
  border: 1px solid #dee2e6;
  &:focus {
    outline: none;
    border: 1px solid #86b7fe;
    box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -webkit-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
    -moz-box-shadow: -1px -1px 5px 5px rgba(194, 219, 254, 1);
  }
  width: 90%;
